import HerdrKit
import SwiftUI

/// A terminal color theme: from `themes.json` (generated by `just themes` from Ghostty's collection),
/// or imported by the user (`ThemeStore`).
struct TerminalTheme: Codable, Identifiable, Hashable {
    let id: String
    let name: String
    let dark: Bool
    /// The 16 ANSI colors as `#rrggbb`.
    let ansi: [String]
    let background: String
    let foreground: String
    let cursor: String
    let selection: String

    var backgroundRGB: RGB { RGB(hex: background) }
    var foregroundRGB: RGB { RGB(hex: foreground) }
    var cursorRGB: RGB { RGB(hex: cursor) }
    var ansiRGB: [RGB] { ansi.map(RGB.init(hex:)) }

    /// Told to the core, so programs that ask (OSC 10/11) get the colors we draw.
    var displayFacts: DisplayFacts { DisplayFacts(fg: foreground, bg: background, cursor: cursor) }

    func color(_ hex: String) -> Color { Color(uiColor: UIColor(RGB(hex: hex))) }
    func ansiColor(_ index: Int) -> Color { color(ansi[index]) }

    var isImported: Bool { id.hasPrefix(ThemeStore.idPrefix) }

    func hasSameColors(as other: TerminalTheme) -> Bool {
        ansi.map { $0.lowercased() } == other.ansi.map { $0.lowercased() }
            && background.lowercased() == other.background.lowercased()
            && foreground.lowercased() == other.foreground.lowercased()
            && cursor.lowercased() == other.cursor.lowercased()
            && selection.lowercased() == other.selection.lowercased()
    }

    /// The built-in themes.
    static let all: [TerminalTheme] = {
        guard let url = Bundle.main.url(forResource: "themes", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let themes = try? JSONDecoder().decode([TerminalTheme].self, from: data), !themes.isEmpty
        else { return [fallback] }
        return themes
    }()

    static var darkThemes: [TerminalTheme] { all.filter(\.dark) }
    static var lightThemes: [TerminalTheme] { all.filter { !$0.dark } }

    static let defaultDark = "hirte-dark"
    static let defaultLight = "hirte-light"

    /// Built-in or imported, with the brightness asked for; else the default of that brightness.
    static func find(_ id: String, dark: Bool, store: ThemeStore = .shared) -> TerminalTheme {
        store.imported.first { $0.id == id && $0.dark == dark }
            ?? all.first { $0.id == id && $0.dark == dark }
            ?? all.first { $0.id == (dark ? defaultDark : defaultLight) }
            ?? fallback
    }

    /// The theme for a color scheme, from the user's two choices.
    static func current(_ scheme: ColorScheme, light: String, dark: String) -> TerminalTheme {
        scheme == .dark ? find(dark, dark: true) : find(light, dark: false)
    }

    /// Only if themes.json is missing.
    private static let fallback = TerminalTheme(
        id: defaultDark, name: "Hirte Dark", dark: true,
        ansi: ["#21252b", "#e06c75", "#98c379", "#e5c07b", "#61afef", "#c678dd", "#56b6c2", "#abb2bf",
               "#767676", "#e06c75", "#98c379", "#e5c07b", "#61afef", "#c678dd", "#56b6c2", "#abb2bf"],
        background: "#1f2124", foreground: "#d9dad8", cursor: "#f2b33d", selection: "#3a3d42")

    static let lightKey = "theme.light"
    static let darkKey = "theme.dark"
}

/// Light, dark, or whatever the system uses; for the whole app.
enum Appearance: String, CaseIterable, Identifiable {
    case system, light, dark

    var id: Self { self }
    var title: String { rawValue.capitalized }
    var style: UIUserInterfaceStyle {
        switch self {
        case .system: .unspecified
        case .light: .light
        case .dark: .dark
        }
    }

    /// Sets it on every window, so everything follows at once, sheets that are open included.
    func apply() {
        for scene in UIApplication.shared.connectedScenes {
            for window in (scene as? UIWindowScene)?.windows ?? [] {
                window.overrideUserInterfaceStyle = style
            }
        }
    }

    static let key = "appearance"
}

extension RGB {
    /// From `#rrggbb`; black if it doesn't parse.
    init(hex: String) {
        let value = UInt32(hex.trimmingCharacters(in: CharacterSet(charactersIn: "#")), radix: 16) ?? 0
        self.init(r: UInt8(value >> 16 & 0xff), g: UInt8(value >> 8 & 0xff), b: UInt8(value & 0xff))
    }

    /// As `#rrggbb`.
    var hex: String { String(format: "#%02x%02x%02x", r, g, b) }
}
